// Loads the columnar data and the config generated by serialize_json.py.
// Shapes are validated on the Python side, so the JSON is only cast here.

const configs = import.meta.glob('./data/config.json', { eager: true, import: 'default' });
const raws = import.meta.glob('./data/data.json', { eager: true, query: '?raw', import: 'default' });

const config = (Object.values(configs)[0] as Config | undefined) ?? {
    labels: {},
    summary: [],
    overview: [],
    unplottable: []
};
const raw = (Object.values(raws)[0] as string | undefined) ?? null;

import { buildDataset, type Config, type RawData } from '#lib/metrics.ts';
export const Data = raw === null ? null : buildDataset(JSON.parse(raw) as RawData, config as Config);
